+// In-memory note store. One instance per server. Deleted notes stay in `notes` with a deletedAt until the TTL passes.
+export function createStore({ now = Date.now } = {}) {
+  let notes = [];
   let nextId = 1;
+  const isLive = (n) => !n.deletedAt;
+  const expired = (n) => now() - Date.parse(n.deletedAt) > TRASH_TTL_MS;
+  const purge = () => { notes = notes.filter((n) => isLive(n) || !expired(n)); };
