       // newest first
-      return [...notes].sort((a, b) => a.createdAt < b.createdAt);
+      return notes.filter(isLive).sort((a, b) => a.createdAt < b.createdAt);
     },
     get(id) {
-      return notes.find((n) => n.id === id);
+      return notes.find((n) => n.id === id && isLive(n));
     },
     update(id, fields) {
-      const note = notes.find((n) => n.id === id);
+      const note = this.get(id);
       if (note) Object.assign(note, fields);
       return note;
     },
     remove(id) {
-      const i = notes.findIndex((n) => n.id === id);
-      if (i === -1) return false;
-      notes.splice(i, 1);
+      const note = this.get(id);
+      if (!note) return false;
+      note.deletedAt = new Date(now()).toISOString();
+      purge();
       return true;
     },
+    trash(owner) {
+      purge();
+      return notes.filter((n) => !isLive(n) && n.owner === owner).sort((a, b) => b.deletedAt.localeCompare(a.deletedAt));
+    },
+    // Returns { note } or { error: 'notfound' | 'notdeleted' | 'expired' }.
+    restore(id, owner) {
+      const note = notes.find((n) => n.id === id && n.owner === owner);
+      if (!note) return { error: 'notfound' };
+      if (isLive(note)) return { error: 'notdeleted' };
+      if (expired(note)) return { error: 'expired' };
+      delete note.deletedAt;
+      return { note };
+    },
   };
 }
diff --git a/tests/trash.test.mjs b/tests/trash.test.mjs
new file mode 100644
index 0000000..07b64b3
--- /dev/null
+++ b/tests/trash.test.mjs
@@ -0,0 +1,83 @@
+import { test, before, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { createApp } from '../src/app/server.js';
+
+const DAY = 24 * 60 * 60 * 1000;
+let server, base, clock = Date.parse('2026-01-01T00:00:00Z');
+before(async () => {
+  server = createApp({ now: () => clock }).listen(0);
+  await new Promise((r) => server.once('listening', r));
+  base = `http://127.0.0.1:${server.address().port}`;
+});
+after(() => server.close());
+
+const call = (method, path, user, body) => fetch(base + path, {
+  method, headers: { 'content-type': 'application/json', ...(user ? { 'x-user': user } : {}) }, body: body && JSON.stringify(body),
+});
+const make = async (user, title) => (await call('POST', '/notes', user, { title })).json();
+const trashIds = async (user) => (await (await call('GET', '/trash', user)).json()).map((n) => n.id);
+
+test('Ç-01.1 deleted note leaves the notes endpoints and shows up in the trash', async () => {
+  const note = await make('ayse', 'sil');
+  await call('DELETE', `/notes/${note.id}`, 'ayse');
+  assert.equal((await call('GET', `/notes/${note.id}`, 'ayse')).status, 404);
+  assert.equal((await call('PATCH', `/notes/${note.id}`, 'ayse', { title: 'x' })).status, 404);
+  assert.equal((await call('DELETE', `/notes/${note.id}`, 'ayse')).status, 404);
+  const ids = (await (await call('GET', '/notes', 'ayse')).json()).map((n) => n.id);
+  assert.ok(!ids.includes(note.id));
+  assert.ok((await trashIds('ayse')).includes(note.id));
+});
+
+test('Ç-01.2 restore brings the note back and empties it from the trash', async () => {
+  const note = await make('ayse', 'geri');
+  await call('DELETE', `/notes/${note.id}`, 'ayse');
+  const r = await call('POST', `/notes/${note.id}/restore`, 'ayse');
+  assert.equal(r.status, 200);
+  const back = await r.json();
+  assert.equal(back.title, 'geri');
+  assert.equal(back.deletedAt, undefined);
+  assert.equal((await call('GET', `/notes/${note.id}`, 'ayse')).status, 200);
+  assert.ok(!(await trashIds('ayse')).includes(note.id));
+});
+
+test('Ç-01.3 restore works on day 30, fails after 30 days', async () => {
+  const a = await make('ayse', 'sınırda');
+  const b = await make('ayse', 'geç');
+  await call('DELETE', `/notes/${a.id}`, 'ayse');
+  await call('DELETE', `/notes/${b.id}`, 'ayse');
+  clock += 30 * DAY;
+  assert.equal((await call('POST', `/notes/${a.id}/restore`, 'ayse')).status, 200);
+  clock += 1;
+  assert.equal((await call('POST', `/notes/${b.id}/restore`, 'ayse')).status, 410);
+  assert.ok(!(await trashIds('ayse')).includes(b.id));
+});
+
+test('Ç-01.4 restore of unknown or non-deleted note is rejected', async () => {
+  const note = await make('ayse', 'canlı');
+  assert.equal((await call('POST', `/notes/${note.id}/restore`, 'ayse')).status, 409);
+  assert.equal((await call('POST', '/notes/yok/restore', 'ayse')).status, 404);
+});
+
+test('Ç-01.5 trash lists newest deletion first', async () => {
+  const a = await make('can', 'a');
+  const b = await make('can', 'b');
+  await call('DELETE', `/notes/${a.id}`, 'can');
+  clock += 1000;
+  await call('DELETE', `/notes/${b.id}`, 'can');
+  assert.deepEqual(await trashIds('can'), [b.id, a.id]);
+});
+
+test('Ç-01.6 attacker: other users cannot see or restore someone else\'s trash', async () => {
+  const note = await make('ayse', 'gizli');
+  await call('DELETE', `/notes/${note.id}`, 'ayse');
+  assert.ok(!(await trashIds('mehmet')).includes(note.id));
+  assert.equal((await call('POST', `/notes/${note.id}/restore`, 'mehmet')).status, 404);
+  assert.equal((await call('GET', '/trash')).status, 401);
+  assert.equal((await call('POST', `/notes/${note.id}/restore`)).status, 401);
+  assert.ok((await trashIds('ayse')).includes(note.id));
+});
+
+test('Ç-01.7 wrong method on trash routes is rejected', async () => {
+  assert.equal((await call('POST', '/trash', 'ayse')).status, 405);
+  assert.equal((await call('GET', '/notes/1/restore', 'ayse')).status, 405);
+});

